                j += 1
            # all indices in [i, j) see the same prefix (strictly less)
            for idx in range(i, j):
                answer[order[idx]] = cur_sum
            # now add these indices to the heap
            for idx in range(i, j):
                val = nums2[order[idx]]
                if len(heap) < k:
                    heapq.heappush(heap, val)
                    cur_sum += val
